// src/App.js
import React, { useState } from 'react';
import { BrowserRouter as Router, Route, Routes, Link, useLocation } from 'react-router-dom';
import Login from './component/Login';
import Signup from './component/Signup';
import HomePage from './component/HomePage';
import './App.css';

function App() {
  const [user, setUser] = useState(null);

  const handleLogin = (userData) => {
    setUser(userData);
    localStorage.setItem('userEmail', userData.email); // Save email on login
  };

  return (
    <Router>
      <AppContent user={user} onLogin={handleLogin} />
    </Router>
  );
}

// Separate component so we can use useLocation
function AppContent({ user, onLogin }) {
  const location = useLocation();
  const hideNav = location.pathname === '/home'; // Hide nav on homepage

  return (
    <>
      <Routes>
        <Route path="/" element={<Login onLogin={onLogin} />} />
        <Route path="/signup" element={<Signup />} />
        <Route path="/home" element={<HomePage user={user} />} />
      </Routes>

      {!hideNav && (
        <nav className="nav-bar">
          <Link to="/">Login</Link>
          <span className="separator">|</span>
          <Link to="/signup">Signup</Link>
        </nav>
      )}
    </>
  );
}

export default App;
